import{_ as e,o as a,c as s,a5 as l}from"./chunks/framework.DJo0M80U.js";const k=JSON.parse('{"title":"iOS 混合应用调试：WebView、原生界面与网络请求","description":"","frontmatter":{"title":"iOS 混合应用调试：WebView、原生界面与网络请求","date":"2026-08-03T22:50:00.000Z","categories":["iOS","调试"],"tags":["WKWebView","Safari Web Inspector","Xcode","DCloud","Instruments"]},"headers":[],"relativePath":"posts/移动开发/iOS/iOS 混合应用调试：WebView、原生界面与网络请求.md","filePath":"posts/移动开发/iOS/iOS 混合应用调试：WebView、原生界面与网络请求.md","lastUpdated":1790163617000}'),t={name:"posts/移动开发/iOS/iOS 混合应用调试：WebView、原生界面与网络请求.md"};function n(p,i,d,o,c,r){return a(),s("div",null,[...i[0]||(i[0]=[l(`<h1 id="ios-混合应用调试-webview、原生界面与网络请求" tabindex="-1">iOS 混合应用调试：WebView、原生界面与网络请求 <a class="header-anchor" href="#ios-混合应用调试-webview、原生界面与网络请求" aria-label="Permalink to &quot;iOS 混合应用调试：WebView、原生界面与网络请求&quot;">​</a></h1><p>iOS 混合应用通常同时包含三种内容：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>iOS 原生窗口和控制器</span></span>
<span class="line"><span>└── UIKit / SwiftUI 原生界面</span></span>
<span class="line"><span>    ├── 原生行情图表</span></span>
<span class="line"><span>    └── DCloud / Uni 容器</span></span>
<span class="line"><span>        └── WKWebView</span></span>
<span class="line"><span>            └── HTML、CSS、JavaScript</span></span></code></pre></div><p>没有一个调试器能完整检查所有层级：</p><ul><li>Safari Web Inspector 负责 <code>WKWebView</code> 内部的 HTML、CSS 和 JavaScript。</li><li>Xcode View Debugger 负责原生 <code>UIView</code>、<code>UIViewController</code> 和约束。</li><li>Instruments 或代理工具负责完整的 App 网络请求。</li></ul><h2 id="一、safari-web-inspector-最适合什么场景" tabindex="-1">一、Safari Web Inspector 最适合什么场景 <a class="header-anchor" href="#一、safari-web-inspector-最适合什么场景" aria-label="Permalink to &quot;一、Safari Web Inspector 最适合什么场景&quot;">​</a></h2><p>Safari Web Inspector 本质上是 iOS WebView 版本的浏览器开发者工具。</p><p>它适合排查：</p><ul><li>Uni 页面中文字大小、行高、颜色。</li><li><code>margin</code>、<code>padding</code>、圆角和边框。</li><li>CSS 是否被其他选择器覆盖。</li><li>安全区变量是否正确。</li><li>元素为什么被遮挡或裁剪。</li><li><code>z-index</code>、绝对定位和弹窗层级。</li><li>JavaScript 报错。</li><li>本地存储、Cookie。</li><li>WebView 发起的页面资源和网络请求。</li><li>页面实际视口尺寸。</li></ul><p>例如当前真机页面中，可以直接看到：</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">font-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 16px;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">font-family</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: &quot;PingFang SC&quot;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">width: 375px;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">height: 812px;</span></span></code></pre></div><p>这比根据截图猜字号和间距准确得多。</p><h3 id="开启方式" tabindex="-1">开启方式 <a class="header-anchor" href="#开启方式" aria-label="Permalink to &quot;开启方式&quot;">​</a></h3><p>从 iOS 16.4 开始，每个 <code>WKWebView</code> 都需要单独设置 <code>isInspectable = true</code>，默认值是 <code>false</code>。<a href="https://developer.apple.com/documentation/webkit/wkwebview/isinspectable" target="_blank" rel="noreferrer">Apple WKWebView 文档</a></p><p>Swift：</p><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEBUG</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> #available</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">iOS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16.4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    webView.isInspectable </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endif</span></span></code></pre></div><p>Objective-C：</p><div class="language-objc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">objc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#if</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DEBUG</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">available</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(iOS </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16.4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    webView.inspectable </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> YES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span></code></pre></div><p>然后完成以下设置：</p><ol><li>iPhone 打开“设置 → Safari → 高级 → 网页检查器”。</li><li>Mac Safari 或 Safari Technology Preview 打开设置。</li><li>在高级设置中启用开发者功能。</li><li>连接手机并启动 Debug App。</li><li>从 <code>Develop → Inspect Apps and Devices</code> 选择设备和页面。</li></ol><p>WebKit 官方也明确说明，远程检查支持开发者 App 中设置为可检查的 <code>WKWebView</code>、<code>JSContext</code> 和 <code>SFSafariViewController</code>。<a href="https://webkit.org/web-inspector/enabling-web-inspector/" target="_blank" rel="noreferrer">WebKit 官方说明</a></p><h3 id="dcloud-uni-的特殊点" tabindex="-1">DCloud/Uni 的特殊点 <a class="header-anchor" href="#dcloud-uni-的特殊点" aria-label="Permalink to &quot;DCloud/Uni 的特殊点&quot;">​</a></h3><p>DCloud 页面外面还有一层自己的 Frame 和 WebEngine，不能只检查最外层 <code>UIView</code>。</p><p>当前 App 中实际链路类似：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PDRCoreAppFrame</span></span>
<span class="line"><span>└── H5WEWKWebview</span></span>
<span class="line"><span>    └── WKWebView</span></span>
<span class="line"><span>        └── Uni 页面 DOM</span></span></code></pre></div><p>必须找到最后真正的 <code>WKWebView</code>，再设置：</p><div class="language-objc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">objc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webView.inspectable </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> YES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>当前真机运行时已经确认有两个可检查的 <code>WKWebView</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pages/index/index[2]</span></span>
<span class="line"><span>View</span></span></code></pre></div><p>另一个 <code>H5WeexViewRootView</code> 不是 <code>WKWebView</code>，因此不能使用 Safari 检查。这类 nvue/Weex 原生渲染页面需要走 Xcode 原生调试链路。</p><h2 id="二、原生元素能不能这样调试" tabindex="-1">二、原生元素能不能这样调试 <a class="header-anchor" href="#二、原生元素能不能这样调试" aria-label="Permalink to &quot;二、原生元素能不能这样调试&quot;">​</a></h2><p>可以调试，但不能使用 Safari Web Inspector。</p><p>Safari 只能进入 WebView 内部，不认识下面这些原生对象：</p><ul><li><code>UIView</code></li><li><code>UILabel</code></li><li><code>UIButton</code></li><li><code>UIViewController</code></li><li>SwiftUI View</li><li>原生行情图表</li><li><code>CALayer</code></li><li>Core Graphics 或 Metal 绘制内容</li></ul><p>原生界面应当使用 Xcode 的 View Debugger。</p><h3 id="使用-xcode-view-debugger" tabindex="-1">使用 Xcode View Debugger <a class="header-anchor" href="#使用-xcode-view-debugger" aria-label="Permalink to &quot;使用 Xcode View Debugger&quot;">​</a></h3><p>操作流程：</p><ol><li>使用 Xcode 运行 App，或者通过 <code>Debug → Attach to Process</code> 附加到正在运行的 App。</li><li>在手机上进入需要检查的页面。</li><li>点击 Xcode 调试栏中的“Debug View Hierarchy”按钮。</li><li>Xcode 暂停 App，并生成当前界面的三维层级。</li><li>选择某个 View，查看右侧 Object Inspector 和 Size Inspector。</li></ol><p>它可以检查：</p><ul><li>View 的真实 <code>frame</code> 和 <code>bounds</code>。</li><li>父子 View 层级。</li><li>哪个 View 覆盖在最上面。</li><li><code>hidden</code>、<code>alpha</code>、背景颜色。</li><li>Safe Area。</li><li>Auto Layout 约束。</li><li>内容是否超出父容器。</li><li><code>clipsToBounds</code> 是否导致裁剪。</li><li>UIKit、SwiftUI 和 WebView 之间的整体层级。</li></ul><p>Apple 官方将它用于检查 UIKit 和 SwiftUI 的尺寸、位置及约束问题，并支持三维展示整个 View 栈。<a href="https://developer.apple.com/documentation/Xcode/diagnosing-issues-in-the-appearance-of-your-running-app" target="_blank" rel="noreferrer">Apple View Debugger 文档</a></p><h3 id="safari-与-xcode-看到的内容有什么区别" tabindex="-1">Safari 与 Xcode 看到的内容有什么区别 <a class="header-anchor" href="#safari-与-xcode-看到的内容有什么区别" aria-label="Permalink to &quot;Safari 与 Xcode 看到的内容有什么区别&quot;">​</a></h3><p>假设当前页面层级为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UIWindow</span></span>
<span class="line"><span>└── MarketDetailViewController</span></span>
<span class="line"><span>    ├── NativeChartView</span></span>
<span class="line"><span>    └── PDRCoreAppFrame</span></span>
<span class="line"><span>        └── WKWebView</span></span>
<span class="line"><span>            └── Uni 弹窗 DOM</span></span></code></pre></div><p>Xcode View Debugger 能看到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UIWindow</span></span>
<span class="line"><span>MarketDetailViewController</span></span>
<span class="line"><span>NativeChartView</span></span>
<span class="line"><span>PDRCoreAppFrame</span></span>
<span class="line"><span>WKWebView</span></span></code></pre></div><p>但看不到 <code>WKWebView</code> 里面的 <code>&lt;div&gt;</code>、文字和 CSS。</p><p>Safari Web Inspector 能看到：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;trade-popup&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;买涨&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>但看不到下面的 <code>NativeChartView</code> 和原生控制器。</p><p>因此混合页面出现遮挡或层级问题时，需要两个工具配合：</p><ul><li>Xcode 确认“整个 WebView 在原生详情的上面还是下面”。</li><li>Safari 确认“弹窗在 WebView 内部的 z-index 是否正确”。</li></ul><h2 id="三、原生行情图表如何调试" tabindex="-1">三、原生行情图表如何调试 <a class="header-anchor" href="#三、原生行情图表如何调试" aria-label="Permalink to &quot;三、原生行情图表如何调试&quot;">​</a></h2><p>原生自绘图表和普通原生控件还有一点区别。</p><p>例如整个 K 线图可能只是一个：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RichChartView</span></span></code></pre></div><p>蜡烛、影线、坐标文字和网格线都是在同一个 View 中通过 Core Graphics 或 Metal 绮制的，不是独立的 <code>UILabel</code> 或 <code>UIView</code>。</p><p>因此 Xcode View Debugger只能检查：</p><ul><li>整个图表 View 的大小。</li><li>图表是否被裁剪。</li><li>图表与顶部、底部安全区的关系。</li><li>图表 View 的原生层级。</li></ul><p>它不能像 HTML 一样点中“某一根 K 线”查看样式。</p><p>内部绘制参数需要通过以下方式检查：</p><ul><li>在布局或绘制方法中设置断点。</li><li>使用 LLDB 查看字体、线宽、缩放比例和坐标。</li><li>Core Graphics 图表检查 <code>UIScreen.main.scale</code> 与像素对齐。</li><li>Metal 图表使用 Xcode Metal Debugger。</li><li>通过截图进行像素级对比。</li></ul><h2 id="四、原生元素的辅助检查工具" tabindex="-1">四、原生元素的辅助检查工具 <a class="header-anchor" href="#四、原生元素的辅助检查工具" aria-label="Permalink to &quot;四、原生元素的辅助检查工具&quot;">​</a></h2><p>Xcode 还提供 Accessibility Inspector：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Xcode</span></span>
<span class="line"><span>→ Open Developer Tool</span></span>
<span class="line"><span>→ Accessibility Inspector</span></span></code></pre></div><p>它适合检查：</p><ul><li>元素是否可点击。</li><li>点击区域是否足够大。</li><li>Accessibility Label。</li><li>文字是否被裁剪。</li><li>颜色对比度。</li><li>VoiceOver 顺序。</li><li>当前原生元素在屏幕上的实际范围。</li></ul><p>Apple 官方说明它可以连接真机、选择前台 App，并直接在手机上高亮目标元素。<a href="https://developer.apple.com/documentation/Accessibility/accessibility-inspector" target="_blank" rel="noreferrer">Accessibility Inspector 文档</a></p><h2 id="五、网络请求怎么抓" tabindex="-1">五、网络请求怎么抓 <a class="header-anchor" href="#五、网络请求怎么抓" aria-label="Permalink to &quot;五、网络请求怎么抓&quot;">​</a></h2><p>网络抓取需要先判断请求是从哪里发出的。</p><h3 id="_1-wkwebview-内部请求" tabindex="-1">1. WKWebView 内部请求 <a class="header-anchor" href="#_1-wkwebview-内部请求" aria-label="Permalink to &quot;1. WKWebView 内部请求&quot;">​</a></h3><p>如果请求由当前 WebView 的以下方式发起：</p><ul><li><code>fetch</code></li><li><code>XMLHttpRequest</code></li><li>页面资源加载</li><li>图片、CSS、JavaScript</li><li>WebSocket</li></ul><p>可以使用 Safari Web Inspector 的 <code>Network</code> 面板：</p><ol><li>打开目标 WebView 的检查器。</li><li>切换到 <code>Network</code>。</li><li>清空旧记录。</li><li>在手机上重新执行操作。</li><li>点击请求查看 Headers、Payload、Response 和 Timing。</li></ol><p>这种方式最适合调试普通 H5 请求。</p><h3 id="_2-uni-api-或原生-sdk-请求" tabindex="-1">2. Uni API 或原生 SDK 请求 <a class="header-anchor" href="#_2-uni-api-或原生-sdk-请求" aria-label="Permalink to &quot;2. Uni API 或原生 SDK 请求&quot;">​</a></h3><p>以下请求不一定出现在 Safari Network 中：</p><ul><li><code>uni.request</code></li><li><code>uni.connectSocket</code></li><li>DCloud 原生网络模块。</li><li>iOS 原生 <code>URLSession</code>。</li><li>原生行情 WebSocket。</li><li>登录、运营商认证等第三方 SDK。</li><li>CTP 或行情组件自己的网络连接。</li></ul><p>原因是它们可能通过 JS Bridge 交给原生层执行，并不是由当前 <code>WKWebView</code> 的 WebKit 网络进程发起。</p><p>DCloud 官方也将 <code>uni.request</code>、WebSocket、上传下载等定义为跨平台 App API，而不只是浏览器中的 XHR。<a href="https://uniapp.dcloud.net.cn/api/request/request" target="_blank" rel="noreferrer">DCloud 网络 API</a></p><h3 id="_3-使用-instruments-抓原生-http" tabindex="-1">3. 使用 Instruments 抓原生 HTTP <a class="header-anchor" href="#_3-使用-instruments-抓原生-http" aria-label="Permalink to &quot;3. 使用 Instruments 抓原生 HTTP&quot;">​</a></h3><p>原生请求推荐使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Xcode</span></span>
<span class="line"><span>→ Product</span></span>
<span class="line"><span>→ Profile</span></span>
<span class="line"><span>→ Network</span></span></code></pre></div><p>开始录制后，在手机上重现操作。</p><p><code>HTTP Traffic</code> 可以查看：</p><ul><li>请求 URL。</li><li>HTTP 方法。</li><li>Request Header。</li><li>Request Body。</li><li>Response Header。</li><li>Response Body。</li><li>DNS、连接和等待耗时。</li><li>请求属于哪个 <code>URLSession</code>。</li><li>HTTP 重定向和多次事务。</li></ul><p>Apple 官方说明 Instruments 能捕获 URL Loading System 中加密和未加密的 HTTP 流量，并在分析记录里以未加密形式保存请求内容，因此调试账号、Token 和交易数据时要妥善处理 trace 文件。<a href="https://developer.apple.com/documentation/Foundation/analyzing-http-traffic-with-instruments" target="_blank" rel="noreferrer">Apple HTTP Traffic 文档</a></p><h3 id="_4-使用-charles-或-proxyman-抓整机流量" tabindex="-1">4. 使用 Charles 或 Proxyman 抓整机流量 <a class="header-anchor" href="#_4-使用-charles-或-proxyman-抓整机流量" aria-label="Permalink to &quot;4. 使用 Charles 或 Proxyman 抓整机流量&quot;">​</a></h3><p>当请求来源不明确时，可以使用系统代理：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>iPhone</span></span>
<span class="line"><span>→ 当前 Wi-Fi</span></span>
<span class="line"><span>→ 配置代理</span></span>
<span class="line"><span>→ 手动</span></span>
<span class="line"><span>→ Mac IP + 代理端口</span></span></code></pre></div><p>然后在手机上安装并信任调试证书。</p><p>这种方式适合：</p><ul><li>WebView 请求。</li><li>Uni 原生请求。</li><li><code>URLSession</code> 请求。</li><li>第三方 SDK 请求。</li><li>普通 HTTPS 和 WebSocket。</li><li>判断请求到底有没有发出。</li></ul><p>但有两个限制：</p><ul><li>使用证书绑定（Certificate Pinning）的请求通常无法解密。</li><li>私有二进制 TCP、行情协议或经过二次加密的数据，即使抓到连接，也不一定能看懂业务内容。</li></ul><p>不要为了抓包关闭正式环境的证书校验；应使用 Debug 环境或专门的测试开关。</p><h2 id="六、当前项目的推荐组合" tabindex="-1">六、当前项目的推荐组合 <a class="header-anchor" href="#六、当前项目的推荐组合" aria-label="Permalink to &quot;六、当前项目的推荐组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>调试目标</th><th>首选工具</th></tr></thead><tbody><tr><td>Uni 弹窗字体、间距、颜色</td><td>Safari Web Inspector</td></tr><tr><td>Uni 弹窗遮罩、DOM 层级</td><td>Safari Web Inspector</td></tr><tr><td>Uni JavaScript 报错</td><td>Safari Console</td></tr><tr><td>原生详情与 Uni WebView 的前后关系</td><td>Xcode View Debugger</td></tr><tr><td>原生状态栏、安全区、控制器层级</td><td>Xcode View Debugger</td></tr><tr><td>原生图表整体尺寸和裁剪</td><td>Xcode View Debugger</td></tr><tr><td>K 线、影线、字体的具体绘制参数</td><td>LLDB、绘制代码断点、截图对比</td></tr><tr><td>WebView 的 fetch/XHR</td><td>Safari Network</td></tr><tr><td><code>uni.request</code>、原生 SDK、<code>URLSession</code></td><td>Instruments HTTP Traffic</td></tr><tr><td>整机 HTTPS/WebSocket 排查</td><td>Charles 或 Proxyman</td></tr><tr><td>点击区域、可访问性、文字裁剪</td><td>Accessibility Inspector</td></tr></tbody></table><p>最核心的结论是：</p><blockquote><p>Safari 负责 WebView 内部，Xcode 负责原生 View 外部，Instruments 或代理工具负责完整网络。混合应用需要组合使用，不能期待一个工具同时看穿所有层级。</p></blockquote>`,101)])])}const b=e(t,[["render",n]]);export{k as __pageData,b as default};
